package org.afetatlas.offline;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
final class ExpandedGuides {
  static List<Guides.Entry> all(){
    ArrayList<Guides.Entry> entries=new ArrayList<>();
    entries.add(new Guides.Entry("Barınak ve kamp","Gecelik barınma kararı","Önce hava durumunu, gün ışığını ve yerin güvenliğini değerlendir. Sel yatağı, devrilebilecek ağaç altı, kaya düşme hattı ve çığ yamacından kaçın. Barınağın yer yalıtımını ve havalandırmasını önceden düzenle."));
    entries.add(new Guides.Entry("Barınak ve kamp","Çadır için zemin seçimi","Düz, sağlam ve su biriktirmeyen bir yer seç; kuru dere yataklarına kurulma. Gece rüzgâr yönü değişebileceği için çadırı sağlam sabitle. Kamp kurallarına ve korunan alan kısıtlarına uy."));
    entries.add(new Guides.Entry("Barınak ve kamp","Çadır su yalıtımı","Dış tente ve iç kumaşın birbirine yapışmamasını sağla. Yağmur altında çukur kazmak araziye zarar verebilir ve sel riskini artırabilir. Dikişler hasarlıysa güvenli kuru alana geçmeyi öncele."));
    entries.add(new Guides.Entry("Barınak ve kamp","Uyku tulumu sıcaklık dereceleri","Konfor sıcaklığı etiketi, kişinin ve koşulların tamamını garanti etmez. Zeminden yalıtım ve kuru katmanlar da gereklidir. Aşırı soğukta barınağı terk ederek güvenli kapalı ortama geç."));
    entries.add(new Guides.Entry("Barınak ve kamp","Zemin yalıtımı","Toprak ısıyı hızla çekebilir; kuru mat veya uygun yalıtım kullan. Islak malzemenin ısı koruma performansı düşer. Üşüme ve bilinç değişikliği hipotermi açısından değerlendirilmelidir."));
    entries.add(new Guides.Entry("Barınak ve kamp","Rüzgâra karşı korunma","Rüzgâr kesen doğal veya güvenli yapısal korunak seç. Gevşek dalların ve devrilme riski taşıyan ağaçların altında kalma. Çadırda açık alev veya yakıtlı ısıtıcı kullanma."));
    entries.add(new Guides.Entry("Barınak ve kamp","Kapalı alanda havalandırma","Jeneratör, gaz ocağı ve mangalı çadır, araç veya kapalı barınakta çalıştırma. Karbonmonoksit kokusuzdur ve ölümcül olabilir. Yeterli temiz hava ve uygun CO alarmı hayati önem taşır."));
    entries.add(new Guides.Entry("Barınak ve kamp","Yağmur altında kuru kalma","Yağmurluğu katmanların üzerine giy ve ıslanan iç katmanı değiştir. Ayakkabı içinde su birikimini azalt; uzun süre ıslak çorapla kalma. Islaklıkla birlikte rüzgâr hipotermi riskini artırır."));
    entries.add(new Guides.Entry("Barınak ve kamp","Kamp yerinde yangın riski","Kuru ot, yaprak ve çam iğnesi yakınında açık alev bulundurma. Yerel orman yangını yasağını izle. Herhangi bir ateşin tamamen söndüğünden emin olmadan bölgeden ayrılma."));
    entries.add(new Guides.Entry("Barınak ve kamp","Barınaktan güvenli ayrılma","Ayrılmadan önce kişileri, eşyaları ve atıkları sayarak kontrol et. Ateş, sıcak kül ve elektrikli cihazları güvenli duruma getir. Dönüş rotasını ve son konumunu güvendiğin birine bildir."));
    entries.add(new Guides.Entry("Doğa navigasyonu","Harita ölçeğini anlama","1:25.000 haritada 1 cm yaklaşık 250 m'yi gösterir; haritanın kendi ölçeğini kontrol et. Eğimli arazi gerçek yürüme mesafesini artırır. Kuş uçuşu mesafeyi ulaşım süresiyle karıştırma."));
    entries.add(new Guides.Entry("Doğa navigasyonu","Koordinat biçimlerini ayırma","Enlem-boylam ile UTM koordinatlarını aynı kutuya yazma. Ondalık derece kullanıyorsan kuzey ve doğu işaretlerini doğru gir. 112'ye biçimi ve yaklaşık hassasiyeti de söyle."));
    entries.add(new Guides.Entry("Doğa navigasyonu","Topoğrafik eşyükselti","Birbirine sık eşyükselti çizgileri daha dik eğime işaret eder. Çizgilerin araziyi kesin güvenli gösterdiğini varsayma. Heyelan, sel ve uçurum risklerini ayrı değerlendir."));
    entries.add(new Guides.Entry("Doğa navigasyonu","Dik yamaçlardan uzak durma","Kısa görünen rota derin vadi veya sarp kayalık içerebilir. Rotayı sadece kuş uçuşu uzunluğa göre seçme. Geri dönüş için zaman ve enerji payı bırak."));
    entries.add(new Guides.Entry("Doğa navigasyonu","Pusula sapması","Manyetik kuzey ile coğrafi kuzey aynı olmayabilir. Haritanın güncel manyetik sapma bilgisini kontrol et. Elektronik veya metal nesneleri pusuladan uzak tut."));
    entries.add(new Guides.Entry("Doğa navigasyonu","GPS hassasiyeti","Kanyon, yoğun ağaç ve yüksek bina çevresinde konum sapabilir. Tek bir GPS noktasıyla uçuruma veya dere yatağına yaklaşma. Koordinatı harita ve görünür arazi işaretleriyle çapraz kontrol et."));
    entries.add(new Guides.Entry("Doğa navigasyonu","Pil biterse navigasyon","Kâğıt harita, pusula ve önceden hazırlanmış rota notu bulundur. Kaybolduğunda rastgele yürümek yerine güvenli yerde durmayı değerlendir. Mümkünse 112'ye son bilinen koordinatı ilet."));
    entries.add(new Guides.Entry("Doğa navigasyonu","Rota kaydı GPX","GPX dosyası daha önce kaydedilmiş izi gösterir; güvenli veya güncel geçiş garantisi değildir. Hava, heyelan ve yol kapanışlarını ayrıca sorgula. İzde sapma fark edersen güvenli yerde dur."));
    entries.add(new Guides.Entry("Doğa navigasyonu","Kuş uçuşu mesafesi","İki nokta arasındaki düz mesafe gerçek yol ağını hesaba katmaz. Nehir, otoyol, çit ve yasak alan dolanmayı gerektirebilir. Planlama için gerçek güzergâh veya resmî geçiş verisini kullan."));
    entries.add(new Guides.Entry("Doğa navigasyonu","Kaybolduğunda işaret verme","Düdük ve parlak kıyafet gibi güvenli işaret yöntemlerini kullan. Açık alanda görünür olmakla kendini hava veya düşme riskine atma. Kurtarma ekibine mümkünse bulunduğun noktayı tarif et."));
    entries.add(new Guides.Entry("Su hijyeni","Yağmur suyu toplama","Toplama yüzeyinin çatı, boya, kuş dışkısı ve kimyasal kirletici taşıyabileceğini unutma. Temiz kap kullan ve suyu uygun biçimde arıt. Kimyasal kirlenme şüphesinde içme."));
    entries.add(new Guides.Entry("Su hijyeni","Dere suyu riskleri","Akan su temiz görünse bile hayvan dışkısı ve mikroorganizma içerebilir. Yukarı akışta yerleşim, maden veya tarım alanı varsa kimyasal risk olabilir. Güvenli kaynağı önceliklendir."));
    entries.add(new Guides.Entry("Su hijyeni","Kar eriterek su elde etme","Kar temiz görünse bile kirlenmiş olabilir. Karı doğrudan çiğnemek vücut ısısı kaybını artırabilir. Erittiğin suyu uygun içme suyu yöntemiyle değerlendir."));
    entries.add(new Guides.Entry("Su hijyeni","Tuzlu su içilmez","Deniz suyunun tuzu, susuzluğu artırabilir. Kaynatma tuzu uzaklaştırmaz. İçilebilir su için uygun tuz giderme teknolojisi veya güvenilir kaynak gerekir."));
    entries.add(new Guides.Entry("Su hijyeni","Bulanık su berraklaştırma","Çöktürme ve mekanik filtrasyon görünür parçacıkları azaltır. Su berraklaşsa bile mikroplar veya kimyasallar kalabilir. Arıtma etkinliği kirletici türüne bağlıdır."));
    entries.add(new Guides.Entry("Su hijyeni","Mikrop ve kimyasal ayrımı","Kaynatma birçok mikroorganizma açısından faydalıdır ama petrol, pestisit veya ağır metali güvenle gidermez. Şüpheli kimyasal kirlilikte alternatif kaynak bul. Koku yokluğu güvenlik kanıtı değildir."));
    entries.add(new Guides.Entry("Su hijyeni","Su arıtma tableti güvenliği","Sadece içme suyu arıtımı için uygun ve etiketi okunabilir ürün kullan. Temas süresi ve doz üretici talimatına göre değişir. Kimyasal veya radyoaktif kirliliği tek başına çözeceğini varsayma."));
    entries.add(new Guides.Entry("Su hijyeni","Filtre bakımının önemi","Filtrenin ömrü, pore boyutu ve etki ettiği mikroorganizmalar modele bağlıdır. Kirli filtreyi üretici talimatına göre temizle veya değiştir. Donmuş filtre elemanları zarar görebilir."));
    entries.add(new Guides.Entry("Su hijyeni","İshalde susuz kalma","Sık ishal ve kusma su-elektrolit kaybına yol açabilir. Güvenli içme suyu kullan. Kanlı dışkı, belirgin halsizlik, bilinç değişikliği veya çocukta ağır tablo varsa tıbbi yardım al."));
    entries.add(new Guides.Entry("Su hijyeni","Çocuklar için su önceliği","Çocuklar sıcak havada ve ishalde daha hızlı susuz kalabilir. Su kaynağı ve hazırlama kaplarının hijyenini artır. İdrar azalması ve uykuya meyil gibi bulgularda sağlık desteğine başvur."));
    entries.add(new Guides.Entry("Gıda stoklama","Afet için üç günlük gıda planı","Kişi sayısı ve bireysel enerji gereksinimine göre bozulmayan gıda ayır. Açacak, hijyen ve su gereksinimini de hesapla. İlaç ve özel diyet ihtiyaçlarını unutma."));
    entries.add(new Guides.Entry("Gıda stoklama","Konserve kabı deformasyonu","Şişmiş, sızdıran veya ciddi biçimde ezilmiş konserveyi tüketme. Kokusuz toksinler bulunabileceği için tadına bakma. Şüpheli gıdayı güvenli biçimde at."));
    entries.add(new Guides.Entry("Gıda stoklama","Soğuk dolabın elektriği kesilirse","Kapıyı gereksiz açmayarak soğukluğu koru. Bozulabilir gıda sıcaklık ve süre koşullarına göre güvenliğini kaybeder. Güvenli olduğundan emin değilsen tüketme."));
    entries.add(new Guides.Entry("Gıda stoklama","Çiğ et ile hazır gıdayı ayırma","Çiğ et suyu kesme tahtası ve diğer gıdalara bulaşabilir. Ellerini ve yüzeyleri uygun biçimde temizle. Tek bir bıçakla çiğ ve pişmiş gıdayı arka arkaya hazırlama."));
    entries.add(new Guides.Entry("Gıda stoklama","Gıda saklama kabı","Gıda ile temasa uygun, temiz, sızdırmaz kapları kullan. Yakıt ve kimyasal kabını asla gıda kabına dönüştürme. Tarih ve içeriği yaz."));
    entries.add(new Guides.Entry("Gıda stoklama","Kuru bakliyat hazırlığı","Bakliyat pişirmek için su ve yakıt gerektiğini önceden hesapla. Bazı türler yeterli pişmezse sindirim veya toksin sorunu yaratabilir. Enerji kaynağı yoksa hazır tüketilebilir alternatif bulundur."));
    entries.add(new Guides.Entry("Gıda stoklama","Glüten veya alerjen ihtiyacı","Özel diyet gereksinimindeki kişinin güvenli gıdasını ayrı planla. Etiket ve çapraz bulaşma riskini kontrol et. Acil ilaçlarını kişisel planıyla birlikte sakla."));
    entries.add(new Guides.Entry("Gıda stoklama","İçme suyu ile yemek pişirme","Pişirme suyunun güvenliği de önemlidir. Tuz, yağ ve yüksek sıcaklık kirli suyu otomatik olarak güvenli hâle getirmez. Bilinmeyen kimyasal kirlenmede alternatif su kullan."));
    entries.add(new Guides.Entry("Gıda stoklama","Gıda son kullanma tarihi","Son kullanma ve tavsiye edilen tüketim tarihi farklı kavramlardır. Bozulabilir üründe tarih ve saklama koşulunu birlikte değerlendir. Ambalaj bütünlüğünü kontrol et."));
    entries.add(new Guides.Entry("Gıda stoklama","Afet sonrası mutfak temizliği","Sel suyu temas eden mutfak alanlarında kirlenme riski vardır. Elektrik ve gaz güvenliği sağlanmadan cihaz çalıştırma. Uygun temizlik ve dezenfeksiyon için yetkili sağlık önerisini izle."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Artçı depremde hareket","Büyük depremden sonra artçılar olabilir. Hasarlı yapıdan uzak kal ve ikinci bir sarsıntıya karşı ÇÖK–KAPAN–TUTUN hazırlığını sürdür. Yetkilinin yapı güvenliği açıklamasını bekle."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Hasarlı yapıya girme","Taşıyıcı eleman çatlağı veya eğilme görürsen içeri girme. Eşyayı kurtarmak için riskli binaya dönme. Profesyonel yapı güvenliği değerlendirmesi gerekir."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Gaz vanası güvenliği","Gaz kaçağı şüphesinde kıvılcım oluşturma ve güvenli alana çık. Ana vana yalnızca güvenli ve eğitimli kişiler tarafından kapatılmalıdır. Gaz hizmetini yetkili ekip kontrol etsin."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Elektrik panosuna yaklaşım","Su basmış veya hasarlı elektrik tesisatına dokunma. Elektrik kesici kuru ve güvenli yerde değilse kendin müdahale etme. Yetkili elektrikçi ve acil ekip desteği al."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Kırık cam ve kesici atık","Enkaz ve cam parçalarında kalın tabanlı ayakkabı ve uygun el koruması kullan. Bilinmeyen kimyasal veya asbestli malzemeye dokunma. Enkaz ayrıştırma işlemini yetkili ekip planlamalıdır."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Enkaz tozu","Bina tozu solunum yolunu tahriş edebilir, bazı yapılarda tehlikeli lifler bulunabilir. Riskli alana gereksiz girme. Profesyonel temizlik ve uygun solunum koruması gerekebilir."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Sel sonrası küf","Su basmış yapıdaki rutubet ve küf solunum şikâyetlerine neden olabilir. Elektrik güvenliği sağlanmadan temizlik yapma. Geniş küf veya kirli su hasarında uzman yardımını kullan."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Yapı tahliyesinde merdiven","Acil durumda asansörü kullanma. Merdivenin hasarlı olmadığından emin olmadan tehlikeli bölgeye girme. Kalabalıkta itişmeden güvenli çıkışa yönel."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Yıkıntıda kurtarma sınırı","Eğitim ve ekipman olmadan ağır moloz kaldırmaya girişme. İkincil çökme ve gaz kaçağı riski vardır. 112'ye yer ve ses duyulan noktaları bildir."));
    entries.add(new Guides.Entry("Afet sonrası güvenlik","Afet sonrası su şebekesi","Şebeke suyu resmî olarak güvenli ilan edilmemişse içme amaçlı kullanma. Boru hasarı suya kirletici karıştırabilir. Resmî kaynatma uyarısının ne tür kirlenmeyi hedeflediğini kontrol et."));
    entries.add(new Guides.Entry("Mevsim koşulları","Hissedilen sıcaklık","Rüzgâr, nem ve ıslak kıyafet vücudun ısı kaybını artırabilir. Termometre değeri tek başına hipotermi riskini anlatmaz. Barınak ve kuru katman planla."));
    entries.add(new Guides.Entry("Mevsim koşulları","Buzlanmada yürüme","Kısa, kontrollü adımlar at ve tabanı tutan ayakkabı kullan. Ellerini denge için serbest tut. Dik buzlu yüzeyde gerekirse geri dön veya güvenli yol ara."));
    entries.add(new Guides.Entry("Mevsim koşulları","Kar altında kalma","Kar ve soğukta solunum ile hipotermi acil önceliktir. Çığ alanında ikinci çığ riski vardır; eğitimsiz kurtarmaya girme. 112'ye olayın konumunu ve gözlemleri bildir."));
    entries.add(new Guides.Entry("Mevsim koşulları","Güneş yanığı","Güneşten çık ve cildi serin tut. Su tüketimini sürdür; kabarcıkları patlatma. Geniş yanık, ateş veya bilinç bozukluğunda sağlık yardımı al."));
    entries.add(new Guides.Entry("Mevsim koşulları","Sıcak araçta mahsur kalma","Park etmiş araç çok kısa sürede tehlikeli ısınabilir. Çocuk ve hayvanı araçta yalnız bırakma. Riskli durumda 112'yi ara ve hızlı güvenli kurtarma prosedürünü izle."));
    entries.add(new Guides.Entry("Mevsim koşulları","Yüksek rakım belirtileri","Baş ağrısı, bulantı ve halsizlik irtifa rahatsızlığına işaret edebilir. Belirtiler kötüleşiyorsa yükselmeyi durdur ve güvenli biçimde alçalmayı değerlendir. Bilinç veya solunum değişikliğinde acil yardım gerekir."));
    entries.add(new Guides.Entry("Mevsim koşulları","Dolu ve aşırı yağış","Sağlam kapalı yapıya gir; cam ve açık pencerelerden uzak dur. Dere yatağı ve alçak geçitte su hızla yükselebilir. Meteorolojik duyuruları izle."));
    entries.add(new Guides.Entry("Mevsim koşulları","Sisli araç kullanımı","Görüş mesafesine göre hızı düşür ve takip mesafesini artır. Dörtlü ikaz lambalarını rutin seyir lambası gibi kullanma. Güvenli duruş noktası bulamıyorsan sert manevralardan kaçın."));
    entries.add(new Guides.Entry("Mevsim koşulları","Tipide yolunu kaybetme","Görüş ve yön kaybolduğunda gelişigüzel yürümek riskli olabilir. Korunaklı alanda kal, bulunduğun konumu kaydet ve yardım çağır. Egzozlu cihazları kapalı ortamda kullanma."));
    entries.add(new Guides.Entry("Mevsim koşulları","Aşırı nem ve sıcak","Yüksek nem terin buharlaşmasını azaltır. Fiziksel eforu hafiflet ve serin ortam bul. Bilinç değişikliği, bayılma veya ciddi halsizlikte 112'yi ara."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","Açık yarada enfeksiyon belirtisi","Artan kızarıklık, sıcaklık, irin, ateş ve ağrı enfeksiyona işaret edebilir. Yarayı kirli elle veya bitkisel karışımla kurcalama. Sağlık değerlendirmesini geciktirme."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","Kan sulandırıcı ilaç ve yaralanma","Kan sulandırıcı kullananlarda küçük görünür travmalar da ciddi olabilir. Baş yaralanması sonrası acil değerlendirme önemlidir. İlaç dozunu kendi başına değiştirme."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","Tetanos riski","Kirli ve delici yaralarda tetanos aşı geçmişini sağlık profesyoneline bildir. Yarayı uygun şekilde temizle; derin yarayı kendi başına kapatmaya çalışma. Aşı gereksinimi kişisel takvime bağlıdır."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","Enfekte suya temas","Sel ve atık suyla temas sonrası cilt yaralarını koru. Temas eden giysiyi değiştir, uygun hijyen sağla. Ateş, ishal veya enfeksiyon belirtisinde sağlık kuruluşuna başvur."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","Ayak sağlığı uzun yürüyüş","Uygun ayakkabı ve kuru çorap sürtünme kabarcıklarını azaltır. Su toplanan alanı kirli aletle delme. Artan ağrı ve kızarıklıkta sağlık desteği al."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","Göz koruyucu ekipman","Toz, duman ve kimyasal sıçrama riskinde göreve uygun gözlük kullan. Kontakt lens kimyasal göz yıkamasını geciktirmemelidir. Görme kaybı ve şiddetli ağrıda acil yardım gerekir."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","Maske ve solunum koruması","Kumaş maske gaz veya oksijen yetersizliğinden korumaz. Partikül filtreli maskenin uygun oturması gerekir; tehlikeli gaz ortamına izinsiz girme. Koruyucu donanım uzman değerlendirmesi ister."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","Uyku ve karar kalitesi","Uykusuzluk risk değerlendirmesini ve koordinasyonu bozabilir. Nöbetleşe dinlenme ve görev paylaşımı planla. Yorgunlukla tehlikeli araç veya makine kullanma."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","Stres anında iletişim","Kısa, açık talimatlar ver; kimlerin nerede olduğunu tekrar teyit et. Çocuk ve kırılgan kişilere anlaşılır bilgi sağla. Sürekli korku, bilinç değişikliği veya kendine zarar riski varsa profesyonel yardım al."));
    entries.add(new Guides.Entry("Sağlık ve hijyen","İlaçların ısıdan korunması","İlaçlar için etiket ve eczacı saklama talimatına uy. Aşırı sıcak veya donma bazı ilaçları bozabilir. Görünüş normal diye etkinliğin korunduğunu varsayma."));
    return Collections.unmodifiableList(entries);
  }
}